sys_security_acl.script:
(function() {

        //HQ / Super users see everything
        if (gs.hasRole('x_1831875_amp2_0.superuser') || gs.hasRole('admin')) {
        return true;

    }
    var userId = gs.getUserID();

    var gr = new GlideRecord('x_1831875_amp2_0_user_fmc_access'); gr.addQuery('u_user', userId); gr.addQuery('u_active', true); gr.query();

    var allowedFMCs = [];

    while (gr.next()) {
        allowedFMCs.push(gr.getValue('u_fmc'));
    }
    if (current.isNewRecord()) {
        return true;
    }
    if (!current.u_fmc) {
        return true;
    }

    return allowedFMCs.indexOf(current.getValue('u_fmc')) > -1;

})();
